from typing import Literal
from app.schemas import CamelModel
from pydantic import Field

class GenerateBriefRequest(CamelModel):
    """Request payload containing the legal research query."""
    query: str


class SearchPlan(CamelModel):
    """Optimized search parameters generated by the query rewrite step."""
    search_query: str
    court: str | None = None


class CitationItem(CamelModel):
    """Structured citation item holding the citation text and docket URL."""
    citation: str
    url: str | None = None


class RevisionEntry(CamelModel):
    """Audit log entry tracking section changes and auditor feedback."""
    target_field: Literal['holding', 'reasoning']
    original_text: str
    revised_text: str
    critique: str
    timestamp: str


class CaseBrief(CamelModel):
    """Structured case brief output."""
    case_name: str
    holding: str
    reasoning: str
    citation: list[str] = Field(
        description="A list of full case names, docket numbers, or URLs referenced in the text for further reading."
    )
    citation_details: list[CitationItem] = Field(
        default_factory=list,
        description='Details about the citation item, if any'
    )
    revision_history: list[RevisionEntry] = Field(
        default_factory=list
    )


class LegalAnalysis(CamelModel):
    """Intermediate extraction schema for legal issues and facts."""
    primary_issue: str
    material_facts: list[str]
    court_reasoning: str


class SingleFieldRepair(CamelModel):
    """Micro-schema constraining the LLM to output only the single repaired paragraph."""
    repaired_text: str


class RepairBriefRequest(CamelModel):
    """Payload for targeted in-place section refinement."""
    current_brief: CaseBrief
    target_field: Literal['holding', 'reasoning']
    instruction: str


class AuditRepairResult(CamelModel):
    """Schema for the Legal Auditor Agent's review decision and critique."""
    approved: bool
    audited_text: str
    critique: str